/// id -> 포켓몬 빠른 조회 (목록을 매번 훑지 않도록)
final Map<int, PokemonInfo> _pokemonIndex = {
  for (final p in <PokemonInfo>[
    hammerTool,
    ...allPokemon,
    ...megaPokemon,
    ...ogerponForms,
  ])
    p.id: p,
};

PokemonInfo? pokemonById(int id) => _pokemonIndex[id];
